lessons.solution:
function createHistory(initial) {
  let versions = [initial];
  let cursor = 0;
  const current = () => versions[cursor];
  return {
    current,
    edit(text) {
      if (text === current()) return current();
      versions = versions.slice(0, cursor + 1);
      versions.push(text); cursor += 1; return current();
    },
    undo() { cursor = Math.max(0, cursor - 1); return current(); },
    redo() { cursor = Math.min(versions.length - 1, cursor + 1); return current(); }
  };
}

